/* ===== ROC / Minguo year -> Gregorian year ===== */
function normalizeROCYearString(s){
  if(!s) return s;
  let x=s;

  // 民國115年8月1日 -> 2026年8月1日
  x=x.replace(/民國\s*(\d{1,3})\s*年/g,(m,y)=>{
    const n=Number(y);
    return (n>=1 && n<=199) ? `${n+1911}年` : m;
  });

  // 115年8月1日 / 115年8月 -> 2026年8月1日 / 2026年8月
  x=x.replace(/(^|[^\d])((?:10\d|11\d|12\d|13\d|14\d|15\d|16\d|17\d|18\d|19\d))年(?=\s*\d{1,2}\s*月)/g,
    (m,prefix,y)=>`${prefix}${Number(y)+1911}年`);

  // 民國115/08/01 -> 2026/08/01
  x=x.replace(/民國\s*(\d{1,3})\s*\/\s*(\d{1,2})\s*\/\s*(\d{1,2})/g,(m,y,mo,d)=>{
    const n=Number(y), mm=Number(mo), dd=Number(d);
    return (n>=1&&n<=199&&mm>=1&&mm<=12&&dd>=1&&dd<=31) ? `${n+1911}/${mo}/${d}` : m;
  });

  // 115/08/01 -> 2026/08/01 (only ROC-like 3-digit years)
  x=x.replace(/(^|[^\d])((?:10\d|11\d|12\d|13\d|14\d|15\d|16\d|17\d|18\d|19\d))\/(\d{1,2})\/(\d{1,2})(?!\d)/g,
    (m,prefix,y,mo,d)=>{
      const mm=Number(mo), dd=Number(d);
      return (mm>=1&&mm<=12&&dd>=1&&dd<=31) ? `${prefix}${Number(y)+1911}/${mo}/${d}` : m;
    });

  return x;
}

const originalDocumentTitle = normalizeROCYearString(document.title);

function cv(s){
  if(!s) return s;

  // Exact mapping for all text currently shipped in this website.
  if(Object.prototype.hasOwnProperty.call(exactMap,s)){
    return exactMap[s];
  }

  // Context-sensitive phrases first.
  let x=s;
  sortedPairs.forEach(([a,b])=>{
    x=x.split(a).join(b);
  });

  // Comprehensive character fallback so newly-added copy doesn't stay Traditional.
  let out='';
  for(const ch of x){
    out += Object.prototype.hasOwnProperty.call(charMap,ch) ? charMap[ch] : ch;
  }
  return out;
}

function getConvertibleTextNodes(root=document.body){
  const walker=document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode(node){
        const p=node.parentElement;
        if(!p) return NodeFilter.FILTER_REJECT;
        if(p.closest('[data-no-convert]')) return NodeFilter.FILTER_REJECT;
        if(['SCRIPT','STYLE','NOSCRIPT','TEXTAREA','CODE','PRE'].includes(p.tagName))
          return NodeFilter.FILTER_REJECT;
        if(!node.nodeValue || !node.nodeValue.trim())
          return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );
  const nodes=[];
  let n;
  while(n=walker.nextNode()) nodes.push(n);
  return nodes;
}

function convertAttributes(isHans, root=document){
  root.querySelectorAll('[title],[aria-label],[alt],[placeholder]').forEach(el=>{
    if(!origAttrs.has(el)){
      const obj={};
      ['title','aria-label','alt','placeholder'].forEach(attr=>{
        if(el.hasAttribute(attr)) obj[attr]=normalizeROCYearString(el.getAttribute(attr));
      });
      origAttrs.set(el,obj);
    }
    const originals=origAttrs.get(el);
    Object.keys(originals).forEach(attr=>{
      el.setAttribute(attr,isHans ? cv(originals[attr]) : originals[attr]);
    });
  });
}

function convertTextNode(node,isHans){
  if(!origText.has(node)){
    const normalized=normalizeROCYearString(node.nodeValue);
    origText.set(node,normalized);
    if(node.nodeValue!==normalized) node.nodeValue=normalized;
  }
  const original=origText.get(node);
  node.nodeValue=isHans ? cv(original) : original;
}

function syncLanguageSwitcher(activeLang){
  document.querySelectorAll('.language-switcher a').forEach(a=>{
    const linkLang=a.getAttribute('title')||'zh-Hant';
    if(linkLang===activeLang) a.setAttribute('aria-current','true');
    else a.removeAttribute('aria-current');
  });
}

function syncLocalizedImages(isHans, root=document){
  const images=[];
  if(root.nodeType===Node.ELEMENT_NODE && root.matches && root.matches('img[data-hans-src]')) images.push(root);
  root.querySelectorAll('img[data-hans-src]').forEach(img=>images.push(img));
  images.forEach(img=>{
    if(!img.dataset.hantSrc) img.dataset.hantSrc=img.getAttribute('src');
    img.setAttribute('src',isHans ? img.dataset.hansSrc : img.dataset.hantSrc);
  });
}

function setLang(l){
  const isHans=l==='zh-Hans';
  document.documentElement.lang=l;

  getConvertibleTextNodes().forEach(node=>convertTextNode(node,isHans));
  convertAttributes(isHans);
  syncLocalizedImages(isHans);

  document.title=isHans ? cv(originalDocumentTitle) : originalDocumentTitle;

  localStorage.setItem('siteLang',l);
  syncLanguageSwitcher(l);
  document.querySelectorAll('.lang-btn').forEach(b=>{
    b.textContent=isHans?'繁':'简';
    b.setAttribute('aria-label',isHans?'切換為繁體中文':'切換為簡體中文');
    b.setAttribute('title',isHans?'切換為繁體中文':'切換為簡體中文');
  });
}

function toggleLang(){
  setLang((localStorage.getItem('siteLang')||'zh-Hant')==='zh-Hant'?'zh-Hans':'zh-Hant');
}

document.addEventListener('DOMContentLoaded',()=>{
  const staticPageLang=document.documentElement.lang;
  if(staticPageLang==='en'||staticPageLang==='ja'){
    localStorage.setItem('siteLang',staticPageLang);
    syncLanguageSwitcher(staticPageLang);
  } else {
    setLang(localStorage.getItem('siteLang')==='zh-Hans'?'zh-Hans':'zh-Hant');
  }

  document.querySelectorAll('.language-switcher a').forEach(a=>a.addEventListener('click',()=>{
    localStorage.setItem('siteLang',a.title||'zh-Hant');
  }));

  // If a page injects new content later, convert it too.
  if(staticPageLang==='en'||staticPageLang==='ja') return;
  const observer=new MutationObserver(mutations=>{
    const isHans=(localStorage.getItem('siteLang')||'zh-Hant')==='zh-Hans';
    mutations.forEach(m=>{
      m.addedNodes.forEach(n=>{
        if(n.nodeType===Node.TEXT_NODE){
          if(n.nodeValue && n.nodeValue.trim()) convertTextNode(n,isHans);
        } else if(n.nodeType===Node.ELEMENT_NODE){
          getConvertibleTextNodes(n).forEach(t=>convertTextNode(t,isHans));
          convertAttributes(isHans,n);
          syncLocalizedImages(isHans,n);
        }
      });
    });
  });
  observer.observe(document.body,{childList:true,subtree:true});
});

