/* ===== Universal mobile dropdown navigation ===== */
function initMobileMenu(){
  document.querySelectorAll('header .nav').forEach(navWrap=>{
    const nav=navWrap.querySelector(':scope > nav');
    if(!nav || navWrap.querySelector('.mobile-menu-toggle')) return;

    const btn=document.createElement('button');
    btn.type='button';
    btn.className='mobile-menu-toggle';
    btn.setAttribute('aria-label','開啟網站選單');
    btn.setAttribute('aria-expanded','false');
    btn.innerHTML='<span class="menu-open-icon" aria-hidden="true">☰</span><span class="menu-close-icon" aria-hidden="true">✕</span>';
    navWrap.insertBefore(btn,nav);

    const closeMenu=()=>{
      navWrap.classList.remove('menu-open');
      btn.setAttribute('aria-expanded','false');
      btn.setAttribute('aria-label','開啟網站選單');
      document.body.classList.remove('mobile-menu-active');
    };

    btn.addEventListener('click',()=>{
      const opening=!navWrap.classList.contains('menu-open');
      document.querySelectorAll('header .nav.menu-open').forEach(other=>{
        if(other!==navWrap) other.classList.remove('menu-open');
      });
      navWrap.classList.toggle('menu-open',opening);
      btn.setAttribute('aria-expanded',opening?'true':'false');
      btn.setAttribute('aria-label',opening?'關閉網站選單':'開啟網站選單');
      document.body.classList.toggle('mobile-menu-active',opening && window.innerWidth<=800);
    });

    nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));

    document.addEventListener('click',e=>{
      if(window.innerWidth<=800 && navWrap.classList.contains('menu-open') && !navWrap.contains(e.target)){
        closeMenu();
      }
    });

    window.addEventListener('resize',()=>{
      if(window.innerWidth>800) closeMenu();
    });
  });
}

document.addEventListener('DOMContentLoaded',initMobileMenu);

/* ===== 護童大頭貼：精簡版 ===== */
function initUniqueBrandAvatars(){
  const scriptEl=[...document.scripts].find(s=>/\/assets\/site\.js(?:\?|$)/.test(s.src));
  const scriptSrc=scriptEl ? scriptEl.src : '';
  const avatarBase=scriptSrc
    ? new URL('./avatars/',scriptSrc)
    : new URL('/child-advocacy-site/assets/avatars/',location.origin);

  const avatarFiles=[
    'avatar-01.jpg','avatar-03.jpg','avatar-07.jpg','avatar-13.jpg',
    'avatar-15.jpg','avatar-18.jpg','avatar-20.jpg',
    'avatar-04.jpg','avatar-11.jpg','avatar-17.jpg'
  ];

  // First clear old V4/V5 assignments.
  document.querySelectorAll('.unique-brand-avatar,.avatar-fallback').forEach(el=>{
    el.classList.remove('unique-brand-avatar','avatar-fallback','nav-brand-avatar','content-brand-avatar');
    el.style.removeProperty('--unique-avatar-image');
  });

  // ① Navigation: every entry can keep one SMALL avatar.
  const navLinks=[...document.querySelectorAll('header .nav > nav > a')];
  navLinks.forEach((el,index)=>{
    const file=avatarFiles[index % 7];
    const url=new URL(file,avatarBase).href;
    el.classList.add('unique-brand-avatar','nav-brand-avatar');
    el.style.setProperty('--unique-avatar-image',`url("${url}")`);
  });

  // ② Main content: maximum THREE avatar buttons per page.
  // Only true primary actions are eligible.
  const prioritySelectors=[
    '.premium-hero-actions a',
    '.hero-actions a',
    '.editorial-read-link',
    '.article-back',
    '.source-btn',
    '.social-page-cta .read-btn',
    '.newest-case-link',
    '.read-btn',
    '.outline-btn'
  ];

  const contentCandidates=[];
  const seen=new Set();
  prioritySelectors.forEach(sel=>{
    document.querySelectorAll(sel).forEach(el=>{
      if(!seen.has(el) && !el.closest('header')){
        seen.add(el);
        contentCandidates.push(el);
      }
    });
  });

  contentCandidates.slice(0,3).forEach((el,index)=>{
    const file=avatarFiles[7+index];
    const url=new URL(file,avatarBase).href;
    el.classList.add('unique-brand-avatar','content-brand-avatar');
    el.style.setProperty('--unique-avatar-image',`url("${url}")`);
  });
}

document.addEventListener('DOMContentLoaded',()=>{
  initUniqueBrandAvatars();
});



/* ===== Court comic lightbox ===== */
function initComicLightbox(){
  const lb=document.getElementById('comicLightbox');
  if(!lb) return;

  const images=[...document.querySelectorAll('.comic-page-image-static img')];
  if(!images.length) return;

  const lbImg=document.getElementById('comicLightboxImg');
  const lbCap=document.getElementById('comicLightboxCaption');
  const closeBtn=lb.querySelector('.lightbox-close');
  const prevBtn=lb.querySelector('.lightbox-prev');
  const nextBtn=lb.querySelector('.lightbox-next');
  let current=0;

  const open=(i)=>{
    current=(i+images.length)%images.length;
    const img=images[current];
    lbImg.src=img.currentSrc||img.src;
    lbImg.alt=img.alt||`法庭紀錄漫畫第 ${current+1} 頁`;
    const card=img.closest('.comic-page');
    const cap=card ? card.querySelector('.comic-page-caption') : null;
    lbCap.textContent=cap ? cap.textContent : (img.alt||'');
    lb.classList.add('show');
    lb.setAttribute('aria-hidden','false');
    document.body.classList.add('lightbox-open');
    if(closeBtn) closeBtn.focus({preventScroll:true});
  };

  const close=()=>{
    lb.classList.remove('show');
    lb.setAttribute('aria-hidden','true');
    document.body.classList.remove('lightbox-open');
    if(images[current]) images[current].focus({preventScroll:true});
  };

  images.forEach((img,i)=>{
    img.tabIndex=0;
    img.setAttribute('role','button');
    img.setAttribute('aria-label',`放大${img.alt||`第 ${i+1} 頁`}`);
    img.addEventListener('click',()=>open(i));
    img.addEventListener('keydown',e=>{
      if(e.key==='Enter'||e.key===' '){
        e.preventDefault();
        open(i);
      }
    });
  });

  if(closeBtn) closeBtn.addEventListener('click',close);
  if(prevBtn) prevBtn.addEventListener('click',()=>open(current-1));
  if(nextBtn) nextBtn.addEventListener('click',()=>open(current+1));
  lb.addEventListener('click',e=>{if(e.target===lb) close();});
  document.addEventListener('keydown',e=>{
    if(!lb.classList.contains('show')) return;
    if(e.key==='Escape') close();
    if(e.key==='ArrowLeft') open(current-1);
    if(e.key==='ArrowRight') open(current+1);
  });
}
document.addEventListener('DOMContentLoaded',initComicLightbox);


/* =====================================================================
   2026-08-09 V11 — Full-site search
   ===================================================================== */
function initSiteSearch(){
  const navs=[...document.querySelectorAll('header .nav > nav')];
  if(!navs.length || document.querySelector('.site-search-overlay')) return;

  const scriptEl=[...document.scripts].find(s=>/\/assets\/site\.js(?:\?|$)/.test(s.src));
  const scriptSrc=scriptEl ? scriptEl.src : new URL('/child-advocacy-site/assets/site.js',location.origin).href;
  const siteBase=new URL('../',scriptSrc);
  const indexUrl=new URL('data/search-index.json',siteBase).href;

  let searchData=null;
  let loadingPromise=null;
  let activeCategory='全部';
  let lastFocused=null;

  const overlay=document.createElement('div');
  overlay.className='site-search-overlay';
  overlay.hidden=true;
  overlay.innerHTML=`
    <section class="site-search-panel" role="dialog" aria-modal="true" aria-labelledby="siteSearchTitle">
      <div class="site-search-panel-head">
        <div><small>SEARCH THE SITE</small><h2 id="siteSearchTitle">全站搜尋</h2></div>
        <button class="site-search-close" type="button" aria-label="關閉搜尋">✕</button>
      </div>
      <div class="site-search-form">
        <label class="site-search-field">
          <span aria-hidden="true">⌕</span>
          <input class="site-search-input" type="search" autocomplete="off"
                 placeholder="輸入案件、人名、日期或關鍵字" aria-label="搜尋網站內容">
          <button class="site-search-clear" type="button" aria-label="清除搜尋">✕</button>
        </label>
      </div>
      <div class="site-search-filters" aria-label="搜尋分類"></div>
      <div class="site-search-status" aria-live="polite">輸入關鍵字開始搜尋</div>
      <div class="site-search-results"></div>
      <div class="site-search-tips">可搜尋「土城」、「白麗芳」、「凱道」、「2026/08/06」等內容。鍵盤可按 <kbd>/</kbd> 或 <kbd>Ctrl</kbd> + <kbd>K</kbd> 開啟搜尋。</div>
    </section>`;
  document.body.appendChild(overlay);

  const input=overlay.querySelector('.site-search-input');
  const closeBtn=overlay.querySelector('.site-search-close');
  const clearBtn=overlay.querySelector('.site-search-clear');
  const results=overlay.querySelector('.site-search-results');
  const status=overlay.querySelector('.site-search-status');
  const filters=overlay.querySelector('.site-search-filters');

  const categories=['全部','社會案件','案件介紹','旁聽紀錄','法庭漫畫','活動紀錄','活動相簿','關於我們','官方社群'];
  categories.forEach(cat=>{
    const b=document.createElement('button');
    b.type='button';
    b.className='site-search-filter'+(cat==='全部'?' is-active':'');
    b.textContent=cat;
    b.dataset.category=cat;
    b.addEventListener('click',()=>{
      activeCategory=cat;
      filters.querySelectorAll('.site-search-filter').forEach(x=>x.classList.toggle('is-active',x===b));
      render();
    });
    filters.appendChild(b);
  });

  navs.forEach(nav=>{
    if(nav.querySelector('.site-search-btn')) return;
    const btn=document.createElement('button');
    btn.type='button';
    btn.className='site-search-btn';
    btn.setAttribute('aria-label','全站搜尋');
    btn.setAttribute('title','全站搜尋（/）');
    btn.innerHTML='<span class="site-search-icon" aria-hidden="true">⌕</span><span class="site-search-label">搜尋</span>';
    const lang=nav.querySelector('.lang-btn');
    nav.insertBefore(btn,lang||null);
    btn.addEventListener('click',()=>openSearch(btn));
  });

  function esc(s=''){
    return String(s).replace(/[&<>"']/g,ch=>({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
    }[ch]));
  }

  function normalize(s=''){
    return String(s)
      .toLowerCase()
      .replace(/[，。、「」『』（）()【】[\]；;：:！!？?．·・—_\-\/\\|]/g,' ')
      .replace(/\s+/g,' ')
      .trim();
  }

  function loadIndex(){
    if(searchData) return Promise.resolve(searchData);
    if(loadingPromise) return loadingPromise;
    status.textContent='正在載入搜尋索引…';
    loadingPromise=fetch(indexUrl,{cache:'no-cache'})
      .then(r=>{
        if(!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then(data=>{
        searchData=data;
        return data;
      })
      .catch(()=>{
        status.textContent='搜尋索引載入失敗，請重新整理頁面後再試。';
        return null;
      });
    return loadingPromise;
  }

  function searchable(item){
    const traditional=[
      item.title,item.category,item.date,item.summary,item.keywords,item.text
    ].join(' ');
    // cv() is the site's Traditional -> Simplified converter.
    // Including both forms lets either script match the same index.
    const simplified=(typeof cv==='function') ? cv(traditional) : traditional;
    return normalize(traditional+' '+simplified);
  }

  function scoreItem(item,q,tokens){
    const title=normalize(item.title+' '+((typeof cv==='function')?cv(item.title):item.title));
    const keywords=normalize(item.keywords+' '+((typeof cv==='function')?cv(item.keywords):item.keywords));
    const summary=normalize(item.summary+' '+((typeof cv==='function')?cv(item.summary):item.summary));
    const hay=searchable(item);

    if(!tokens.every(t=>hay.includes(t))) return -1;
    let score=0;
    if(title.includes(q)) score+=120;
    if(keywords.includes(q)) score+=70;
    if(summary.includes(q)) score+=45;
    if(hay.includes(q)) score+=25;
    tokens.forEach(t=>{
      if(title.includes(t)) score+=24;
      if(keywords.includes(t)) score+=12;
      if(summary.includes(t)) score+=7;
    });
    if(item.date && normalize(item.date).includes(q)) score+=80;
    return score;
  }

  function render(){
    if(!searchData){
      loadIndex().then(()=>render());
      return;
    }
    const q=normalize(input.value);
    const tokens=q.split(' ').filter(Boolean);

    if(!q){
      status.textContent=`已建立 ${searchData.count} 個頁面的搜尋索引`;
      results.innerHTML=`
        <div class="site-search-empty">
          <strong>搜尋護童行動聯盟網站</strong>
          <span>輸入案件名稱、人名、日期或主題，即可搜尋旁聽紀錄、法庭漫畫、活動與相簿。</span>
        </div>`;
      return;
    }

    const found=searchData.items
      .filter(item=>activeCategory==='全部' || item.category===activeCategory)
      .map(item=>({item,score:scoreItem(item,q,tokens)}))
      .filter(x=>x.score>=0)
      .sort((a,b)=>b.score-a.score)
      .slice(0,20);

    status.textContent=`找到 ${found.length} 筆結果${activeCategory!=='全部' ? `・${activeCategory}` : ''}`;

    if(!found.length){
      results.innerHTML=`
        <div class="site-search-empty">
          <strong>沒有找到符合的內容</strong>
          <span>可以縮短關鍵字，或切換到「全部」分類再試一次。</span>
        </div>`;
      return;
    }

    results.innerHTML=found.map(({item})=>{
      const href=new URL(item.url||'./',siteBase).href;
      return `
        <a class="site-search-result" href="${esc(href)}">
          <div class="site-search-result-main">
            <div class="site-search-result-top">
              <span class="site-search-result-category">${esc(item.category)}</span>
              ${item.date?`<span class="site-search-result-date">${esc(item.date)}</span>`:''}
            </div>
            <h3>${esc(item.title)}</h3>
            <p>${esc(item.summary)}</p>
          </div>
          <span class="site-search-result-arrow" aria-hidden="true">→</span>
        </a>`;
    }).join('');
  }

  function openSearch(source){
    lastFocused=source||document.activeElement;
    overlay.hidden=false;
    document.body.classList.add('site-search-open');
    document.querySelectorAll('header .nav.menu-open').forEach(x=>x.classList.remove('menu-open'));
    document.body.classList.remove('mobile-menu-active');
    loadIndex().then(()=>{
      render();
      if((localStorage.getItem('siteLang')||'zh-Hant')==='zh-Hans' && typeof setLang==='function'){
        setLang('zh-Hans');
      }
    });
    requestAnimationFrame(()=>input.focus());
  }

  function closeSearch(){
    overlay.hidden=true;
    document.body.classList.remove('site-search-open');
    if(lastFocused && typeof lastFocused.focus==='function') lastFocused.focus({preventScroll:true});
  }

  input.addEventListener('input',render);
  input.addEventListener('keydown',e=>{
    if(e.key==='Escape') closeSearch();
  });
  clearBtn.addEventListener('click',()=>{
    input.value='';
    render();
    input.focus();
  });
  closeBtn.addEventListener('click',closeSearch);
  overlay.addEventListener('click',e=>{
    if(e.target===overlay) closeSearch();
  });

  document.addEventListener('keydown',e=>{
    const tag=(document.activeElement && document.activeElement.tagName)||'';
    const typing=['INPUT','TEXTAREA','SELECT'].includes(tag);
    if((e.key==='/' && !typing) || ((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='k')){
      e.preventDefault();
      openSearch(document.activeElement);
    }
    if(e.key==='Escape' && !overlay.hidden) closeSearch();
  });
}

/* ===== Homepage impact counters ===== */
function initImpactCounters(){
  const counters=[...document.querySelectorAll('.impact-counter[data-count]')];
  if(!counters.length) return;

  const reduced=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduced){
    counters.forEach(el=>el.textContent=el.dataset.count);
    return;
  }

  const animate=(el)=>{
    if(el.dataset.animated==='1') return;
    el.dataset.animated='1';
    const target=Number(el.dataset.count)||0;
    const duration=820;
    const start=performance.now();
    el.textContent='0';
    const frame=(now)=>{
      const p=Math.min(1,(now-start)/duration);
      const eased=1-Math.pow(1-p,3);
      el.textContent=String(Math.round(target*eased));
      if(p<1) requestAnimationFrame(frame);
      else el.textContent=String(target);
    };
    requestAnimationFrame(frame);
  };

  if(!('IntersectionObserver' in window)){
    counters.forEach(animate);
    return;
  }

  const io=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        animate(entry.target);
        io.unobserve(entry.target);
      }
    });
  },{threshold:.45});

  counters.forEach(el=>io.observe(el));
}

document.addEventListener('DOMContentLoaded',()=>{
  initSiteSearch();
  initImpactCounters();
});


/* =====================================================================
   2026-08-10 — 社會案件雙欄下拉導覽
   ===================================================================== */
function initSocialCaseDropdowns(){
  const groups=[...document.querySelectorAll('.social-case-nav')];
  if(!groups.length) return;
  const closeTimers=new WeakMap();
  const cancelClose=group=>{
    const timer=closeTimers.get(group);
    if(timer) window.clearTimeout(timer);
    closeTimers.delete(group);
  };
  const resetSpecialFeatureState=group=>{
    if(!group.classList.contains('special-feature-nav')) return;
    group.querySelectorAll('.special-feature-case-group').forEach(item=>{
      item.classList.remove('is-expanded','is-feature-click-pinned');
      item.querySelector(':scope > .special-feature-case-toggle')?.setAttribute('aria-expanded','false');
    });
    group.querySelectorAll('.special-feature-prologue-group').forEach(item=>{
      item.classList.remove('is-expanded');
      item.querySelector(':scope > .special-feature-menu-prologue')?.setAttribute('aria-expanded','false');
    });
  };
  const close=(group,force=false)=>{
    cancelClose(group);
    if(!force&&group.classList.contains('is-click-pinned')) return;
    group.classList.remove('is-open','is-click-pinned');
    resetSpecialFeatureState(group);
    const btn=group.querySelector('.social-case-nav-toggle');
    if(btn) btn.setAttribute('aria-expanded','false');
  };
  const open=(group,pinned=false)=>{
    cancelClose(group);
    groups.forEach(g=>{if(g!==group)close(g,true)});
    group.classList.add('is-open');
    group.classList.toggle('is-click-pinned',pinned);
    const btn=group.querySelector('.social-case-nav-toggle');
    if(btn) btn.setAttribute('aria-expanded','true');
  };
  groups.forEach(group=>{
    const btn=group.querySelector('.social-case-nav-toggle');if(!btn)return;
    btn.addEventListener('click',e=>{
      e.stopPropagation();
      group.classList.contains('is-click-pinned') ? close(group,true) : open(group,true);
    });
    group.addEventListener('mouseenter',()=>{
      cancelClose(group);
      const clickOnly=group.classList.contains('special-feature-nav');
      if(window.innerWidth>800&&!clickOnly&&!group.classList.contains('is-open')) open(group,false);
    });
    group.addEventListener('mouseleave',()=>{
      if(window.innerWidth>800){
        cancelClose(group);
        closeTimers.set(group,window.setTimeout(()=>close(group,false),160));
      }
    });
    group.addEventListener('keydown',e=>{if(e.key==='Escape'){close(group,true);btn.focus()}});
    group.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>close(group,true)));
  });
  document.addEventListener('click',e=>groups.forEach(group=>{if(!group.contains(e.target))close(group,true)}));
  window.addEventListener('resize',()=>groups.forEach(group=>close(group,true)));
}
document.addEventListener('DOMContentLoaded',initSocialCaseDropdowns);

/* 2026-08-13 — 社會案件與歷史案件第二層導覽 */
function initNestedCaseMenus(){
  document.querySelectorAll('.social-case-tier,.historical-case-nav .social-case-menu-column').forEach(group=>{
    const button=group.querySelector(':scope > .social-case-tier-toggle,:scope > .historical-region-root-toggle');
    if(!button) return;
    const setExpanded=value=>{group.classList.toggle('is-expanded',value);button.setAttribute('aria-expanded',value?'true':'false')};
    button.addEventListener('click',event=>{
      event.preventDefault();event.stopPropagation();
      const closing=group.classList.contains('is-expanded')||(window.innerWidth>800&&group.matches(':hover')&&!group.classList.contains('is-click-collapsed'));
      group.classList.toggle('is-click-collapsed',closing);
      setExpanded(!closing);
    });
    group.addEventListener('mouseenter',()=>{if(window.innerWidth>800&&!group.classList.contains('is-click-collapsed'))setExpanded(true)});
    group.addEventListener('mouseleave',()=>{if(window.innerWidth>800){group.classList.remove('is-click-collapsed');setExpanded(false)}});
    group.addEventListener('keydown',event=>{if(event.key==='Escape'){setExpanded(false);button.focus()}});
  });
}
document.addEventListener('DOMContentLoaded',initNestedCaseMenus);

/* 2026-08-13 — 歷史案件：地區先行的第二層導覽 */
function initHistoricalRegionMenus(){
  document.querySelectorAll('.historical-region-group').forEach(group=>{
    const button=group.querySelector('.historical-region-toggle');
    if(!button) return;
    const setExpanded=expanded=>{
      group.classList.toggle('is-expanded',expanded);
      button.setAttribute('aria-expanded',expanded?'true':'false');
    };
    button.addEventListener('click',event=>{
      event.preventDefault();
      event.stopPropagation();
      setExpanded(!group.classList.contains('is-expanded'));
    });
    group.addEventListener('mouseenter',()=>{if(window.innerWidth>800)setExpanded(true)});
    group.addEventListener('mouseleave',()=>{if(window.innerWidth>800)setExpanded(false)});
    group.addEventListener('focusin',()=>setExpanded(true));
    group.addEventListener('focusout',()=>window.setTimeout(()=>{
      if(!group.contains(document.activeElement)) setExpanded(false);
    },0));
    group.addEventListener('keydown',event=>{
      if(event.key==='Escape'){
        setExpanded(false);
        button.focus();
      }
    });
  });
}
document.addEventListener('DOMContentLoaded',initHistoricalRegionMenus);

/* =====================================================================
   2026-08-15 — 特別專題：桌機 hover、click 固定與手機逐層收放
   ===================================================================== */
function initSpecialFeatureColumns(){
  const menus=[...document.querySelectorAll('.special-feature-nav-menu')];
  if(!menus.length) return;

  const collapse=(group,clearPinned=true)=>{
    group.classList.remove('is-expanded');
    if(clearPinned) group.classList.remove('is-feature-click-pinned');
    const button=group.querySelector('.special-feature-case-toggle');
    if(button) button.setAttribute('aria-expanded','false');
    group.querySelectorAll('.special-feature-prologue-group.is-expanded').forEach(nested=>{
      nested.classList.remove('is-expanded');
      nested.querySelector('.special-feature-menu-prologue')?.setAttribute('aria-expanded','false');
    });
  };
  const expand=(group,pinned=false)=>{
    const menu=group.closest('.special-feature-nav-menu');
    if(menu) menu.querySelectorAll('.special-feature-case-group').forEach(item=>{
      if(item!==group) collapse(item);
    });
    group.classList.add('is-expanded');
    group.classList.toggle('is-feature-click-pinned',pinned);
    const button=group.querySelector('.special-feature-case-toggle');
    if(button) button.setAttribute('aria-expanded','true');
  };

  menus.forEach(menu=>{
    const groups=[...menu.querySelectorAll('.special-feature-case-group')];
    groups.forEach((group,index)=>{
      const button=group.querySelector('.special-feature-case-toggle');
      if(!button) return;
      button.addEventListener('click',event=>{
        event.preventDefault();
        event.stopPropagation();
        group.classList.contains('is-feature-click-pinned') ? collapse(group) : expand(group,true);
      });
      group.addEventListener('mouseenter',()=>{
        if(window.innerWidth>800&&!group.classList.contains('is-expanded')) expand(group,false);
      });
      group.addEventListener('mouseleave',()=>{
        if(window.innerWidth>800&&!group.classList.contains('is-feature-click-pinned')) collapse(group,false);
      });
      group.addEventListener('focusin',()=>{
        if(window.innerWidth>800&&!group.classList.contains('is-expanded')) expand(group,false);
      });
      group.addEventListener('focusout',()=>window.setTimeout(()=>{
        if(window.innerWidth>800&&!group.contains(document.activeElement)&&!group.classList.contains('is-feature-click-pinned')) collapse(group,false);
      },0));
      group.addEventListener('keydown',event=>{
        if(event.key==='Escape'){
          event.preventDefault();
          collapse(group);
          button.focus();
        }
      });
      button.addEventListener('keydown',event=>{
        if(window.innerWidth>800 && (event.key==='ArrowLeft'||event.key==='ArrowRight')){
          event.preventDefault();
          const step=event.key==='ArrowRight'?1:-1;
          const target=groups[(index+step+groups.length)%groups.length];
          target.querySelector('.special-feature-case-toggle')?.focus();
        }
      });
    });

    const syncMode=()=>{
      groups.forEach(group=>{
        if(window.innerWidth<=800&&!group.classList.contains('is-feature-click-pinned')) collapse(group,false);
        const button=group.querySelector('.special-feature-case-toggle');
        button?.setAttribute('aria-expanded',group.classList.contains('is-expanded')?'true':'false');
      });
    };
    syncMode();
    window.addEventListener('resize',syncMode);
  });
}
document.addEventListener('DOMContentLoaded',initSpecialFeatureColumns);

